# BCAT prompt (bash) - generated by bcat.py
__bcat_prompt() {
    local ec=$?
    local g='' v='' mk sc b
    b=$(command git symbolic-ref --short -q HEAD 2>/dev/null)
    [ -n "$b" ] && g=" ($b)"
    [ -n "$VIRTUAL_ENV" ] && v=" (${VIRTUAL_ENV##*/})"
    if [ "$ec" -eq 0 ]; then
        sc='\[\e[1;32m\]'; mk='✔'
    else
        sc='\[\e[1;31m\]'; mk='✘'
    fi
    PS1="\[\e[1;35m\]▁▂▃ \[\e[1;95m\]silent \[\e[1;35m\]▃▂▁ \[\e[1;96m\]\w\[\e[1;33m\]${g}\n\[\e[1;35m\]⟩ ${sc}\[\e[0m\]"
}
case ";${PROMPT_COMMAND};" in
    *";__bcat_prompt;"*) ;;
    *) PROMPT_COMMAND="__bcat_prompt${PROMPT_COMMAND:+;${PROMPT_COMMAND}}" ;;
esac
